define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_22.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e145044","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_21.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e145148","topics":[]},{"title":"Applying LOTO - MDP","shortdesc":"<p class=\"shortdesc\"><span class=\"ph uicontrol\">Note: <\/span>Prior to applying LOTO to the system do the Disk Wipe procedure, which can be found on the documentation library. Search on document 5500610-1. Apply LOTO to the MDP or the facility PDU before removing power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Applying-LOTO-MDP-Premier_6.html","attributes":{"data-id":"id_2001934"},"menu":{"hasChildren":false},"tocID":"id_2001934-d46e145252","topics":[]},{"title":"Installing the hoist","shortdesc":"<p class=\"shortdesc\">Install the hoist in order to replace components within the Integrated System Cabinet (ISC) and Integrated Cooling Cabinet (ICC).<\/p>","href":"t_InstallingTheHoist_2.html","attributes":{"data-id":"id_2003492"},"menu":{"hasChildren":false},"tocID":"id_2003492-d46e145358","topics":[]},{"title":"Replacing the Facility Plumbing Unit (FPU)","shortdesc":"<p class=\"shortdesc\">This procedure includes the steps needed to drain the ICC primary water circuit and replace the Facility Plumbing Unit (FPU).<\/p>","href":"t_FacilityPlumbingUnitFPUReplacement.html","attributes":{"data-id":"id_2001532"},"menu":{"hasChildren":true},"tocID":"id_2001532-d46e145462","next":"id_2001532-d46e145462"},{"title":"Removing the hoist","shortdesc":"<p class=\"shortdesc\">Remove the hoist beam and return it to its storage location.<\/p>","href":"t_RemovingTheHoist_2.html","attributes":{"data-id":"id_2003868"},"menu":{"hasChildren":false},"tocID":"id_2003868-d46e145671","topics":[]},{"title":"Removing LOTO - MDP","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the MDP or the facility PDU before restoring power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Removing-LOTO-MDP-Premier_5.html","attributes":{"data-id":"id_2001935"},"menu":{"hasChildren":false},"tocID":"id_2001935-d46e145775","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_21.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e145884","topics":[]},{"title":"Adjusting facility water flow rate","shortdesc":"<p class=\"shortdesc\">Use this procedure to check and adjust the current facility water flow rate.<\/p>","href":"t_AdjustingFacilityWaterFlowRate.html","attributes":{"data-id":"id_2004393"},"menu":{"hasChildren":false},"tocID":"id_2004393-d46e145988","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_39.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e146092","topics":[]}]});